  async function savePartner(event){event.preventDefault();try{const values=Object.fromEntries(new FormData(event.currentTarget).entries()),code=String(values.customerCode||'').trim(),email=String(values.email||'').trim();if(!code)throw new Error('顧客コードを入力してください。');if(!String(values.name||'').trim())throw new Error('名称を入力してください。');if(!C.validateEmail(email))throw new Error('メールアドレスの形式が不正です。');if(values.cc&&!C.validateEmail(values.cc))throw new Error('CCメールアドレスの形式が不正です。');const partner=Object.fromEntries(C.PARTNER_HEADERS.map(header=>[header,'']));Object.assign(partner,{'顧客コード':code,'名称':String(values.name).trim(),'名称(カナ)':String(values.kana||'').trim(),'敬称':values.honorific||'様','郵便番号':String(values.postal||'').trim(),'都道府県':String(values.prefecture||'').trim(),'住所1':String(values.address1||'').trim(),'住所2':String(values.address2||'').trim(),'電話番号':String(values.phone||'').trim(),'メールアドレス':email,'CCメールアドレス':String(values.cc||'').trim(),'メモ':String(values.memo||'').trim(),'学年':String(values.grade||'').trim(),'教室':String(values.campus||'').trim()});const existing=state.partners.findIndex(item=>String(item['顧客コード'])===String(state.editingPartnerCode||code));if(existing>=0)state.partners[existing]=partner;else state.partners.push(partner);persistPartners();renderPartners();renderPartnerOptions();reconcile();await safeApi('importPartners',{partners:state.partners});$('#partnerDialog').close();state.editingPartnerCode=null;alert(`${partner['名称']}を取引先マスタへ${existing>=0?'更新':'登録'}しました。`,'success');}catch(e){alert(e.message,'error');}}
