  async function searchStudent(event){event.preventDefault();const input=event.currentTarget.elements.studentCode,code=C.normalizeStudentCode(input.value),button=$('#searchStudent'),status=$('#studentSearchStatus'),originalText=button.textContent;input.value=code;if(!code)return alert('生徒コードを入力してください。');if(!/^[A-Za-z0-9]+$/.test(code)){input.focus();status.textContent='生徒コードは半角英数で入力してください。';status.className='field-help student-search-error';return;}button.disabled=true;button.textContent='検索しています…';status.textContent='生徒マスタを検索しています…';status.className='field-help student-search-working';$('#studentSearchResult').classList.add('hidden');$('#importStudentPartner').disabled=true;state.studentCandidate=null;try{const student=await api('findStudentForPartner',{studentCode:code});state.studentCandidate=student;$('#studentResultCode').textContent=student.studentCode;$('#studentResultName').textContent=student.name;$('#studentResultGrade').textContent=student.grade||'未登録';$('#studentSearchResult').classList.remove('hidden');status.textContent='氏名と学年を確認し、対象の生徒を選択してください。';status.className='field-help student-search-success';}catch(e){const timedOut=/20秒以内に応答しませんでした/.test(String(e.message||''));status.textContent=timedOut?'生徒マスタに接続できませんでした。少し待ってから「生徒を検索」をもう一度押してください。':`検索できませんでした：${e.message}`;status.className='field-help student-search-error';input.focus();}finally{button.disabled=false;button.textContent=originalText;}}
