  function updateCreateSelectionUi(){const total=state.importInvoices.length,selected=state.createSelected.size,master=$('#createSelectAll'),loggedIn=!!staffSessionToken();if(master){master.checked=total>0&&selected===total;master.indeterminate=selected>0&&selected<total;}$$('#createSelectedCount, #createSelectedCountTop').forEach(count=>count.textContent=`${selected}／${total}件を選択`);$$('[data-save-imported-invoices]').forEach(button=>{button.disabled=selected===0;button.textContent=selected&&!loggedIn?'スタッフログインして保存':'保存して請求書を作成';});$$('[data-remove-create-rows]').forEach(button=>{button.disabled=selected===0;button.textContent=selected?`選択した${selected}件を削除`:'選択した行を削除';});}
  function removeSelectedCreateRows(){const selected=[...state.createSelected].filter(index=>state.importInvoices[index]);if(!selected.length)return;if(!window.confirm(`選択した${selected.length}件をこの一覧から削除します。\n\nまだ保存していないCSVの読込内容が対象です。よろしいですか？`))return;const removing=new Set(selected);state.importInvoices=state.importInvoices.filter((_,index)=>!removing.has(index));state.createSelected=new Set(state.importInvoices.map((_,index)=>index));state.preview=null;renderCreate();$('#invoiceImportSummary').innerHTML=cards({'残り件数':state.importInvoices.length,'削除件数':selected.length,'選択件数':state.createSelected.size});$('#invoiceImportSummary').classList.remove('hidden');alert(`${selected.length}件を一覧から削除しました。`,'success');}
