  function renderPartners(){const tbody=$('#partnerTable tbody');tbody.innerHTML=state.partners.length?state.partners.map(p=>`<tr><td>${esc(p['顧客コード'])}</td><td>${esc(p['名称'])}</td><td>${esc(p['敬称'])}</td><td>${esc(p['郵便番号'])}</td><td>${esc(p['都道府県']+p['住所1']+p['住所2'])}</td><td>${esc(p['電話番号'])}</td><td>${esc(p['メールアドレス'])}</td><td>${esc(p['CCメールアドレス'])}</td><td>${esc(p['メモ'])}</td><td><button class="button secondary compact" type="button" data-edit-partner="${esc(p['顧客コード'])}">編集</button> <button class="button compact-danger" type="button" data-delete-partner="${esc(p['顧客コード'])}">削除</button></td></tr>`).join(''):'<tr class="empty"><td colspan="10">取引先CSVを読み込むか、個別入力してください。</td></tr>';tbody.querySelectorAll('[data-edit-partner]').forEach(button=>button.onclick=()=>openPartnerForm(button.dataset.editPartner));tbody.querySelectorAll('[data-delete-partner]').forEach(button=>button.onclick=()=>openPartnerDelete(button.dataset.deletePartner));}
  function singleDetailRows(){return $$('#singleDetailBody tr').map(row=>({name:row.querySelector('[name="detailName"]').value,unitPrice:row.querySelector('[name="detailUnitPrice"]').value,quantity:row.querySelector('[name="detailQuantity"]').value,unit:row.querySelector('[name="detailUnit"]').value,taxRate:row.querySelector('[name="detailTaxRate"]').value}));}
  function saveSingleDraft(){const form=$('#singleInvoiceForm');if(!form)return;const values={};['partnerCode','invoiceNumber','subject','invoiceDate','dueDate','memo','tags','bank','note'].forEach(name=>values[name]=form.elements[name]?.value||'');localStorage.setItem(SINGLE_DRAFT_KEY,JSON.stringify({values,details:singleDetailRows(),savedAt:new Date().toISOString()}));}
  function restoreSingleDraft(){let draft=null;try{draft=JSON.parse(localStorage.getItem(SINGLE_DRAFT_KEY)||'null');}catch(_){}if(!draft?.values)return false;const form=$('#singleInvoiceForm');Object.entries(draft.values).forEach(([name,value])=>{if(form.elements[name])form.elements[name].value=String(value??'');});if(Array.isArray(draft.details)&&draft.details.length){$('#singleDetailBody').innerHTML='';draft.details.forEach(detail=>addSingleDetail(detail));}updateSingleTotals();setSingleSaveStatus('前回入力途中だった内容を、この端末から復元しました。','working');return true;}
  function updateSingleTotals(){const rows=singleDetailRows();const subtotal=rows.reduce((sum,row)=>sum+Math.round(Number(row.unitPrice||0)*Number(row.quantity||0)),0);const sourceTax=rows.reduce((sum,row)=>{const amount=Math.round(Number(row.unitPrice||0)*Number(row.quantity||0));return sum+Math.round(amount*Number(row.taxRate||0)/100);},0);const total=C.roundToNearest10(subtotal+sourceTax);$('#singleSubtotal').textContent=C.formatYen(subtotal);$('#singleTax').textContent=C.formatYen(total-subtotal);$('#singleTotal').textContent=C.formatYen(total);$$('#singleDetailBody tr').forEach((row,index)=>{const detail=rows[index];row.querySelector('[data-detail-amount]').textContent=C.formatYen(Math.round(Number(detail.unitPrice||0)*Number(detail.quantity||0)));});updateSingleLivePreview();}
  function normalizeDetailNumber(element){if(!element)return;const normalized=String(element.value||'').replace(/[０-９]/g,char=>String.fromCharCode(char.charCodeAt(0)-0xFEE0)).replace(/[，,\s]/g,'').replace(/[．。]/g,'.').replace(/[－−―ー‐‑‒–—]/g,'-');if(element.value!==normalized)element.value=normalized;}
  function bindDetailNumber(element,update){element.addEventListener('input',event=>{if(!event.isComposing){normalizeDetailNumber(element);update();}});element.addEventListener('compositionend',()=>{normalizeDetailNumber(element);update();});element.addEventListener('blur',()=>{normalizeDetailNumber(element);update();});}
  function addSingleDetail(data={},focusName=false){const row=document.createElement('tr');row.innerHTML=`<td><input name="detailName" type="text" inputmode="text" lang="ja" autocomplete="off" value="${esc(data.name||'')}" placeholder="例：授業料・割引" required></td><td><input name="detailUnitPrice" type="text" inputmode="decimal" value="${esc(data.unitPrice??'')}" placeholder="例：25000／割引は-10000" required></td><td><input name="detailQuantity" type="text" inputmode="decimal" value="${esc(data.quantity??1)}" required></td><td><input name="detailUnit" type="text" inputmode="text" lang="ja" value="${esc(data.unit||'')}" placeholder="回・月"></td><td><select name="detailTaxRate"><option value="10" ${Number(data.taxRate??10)===10?'selected':''}>10%</option><option value="8" ${Number(data.taxRate)===8?'selected':''}>8%</option><option value="0" ${Number(data.taxRate)===0?'selected':''}>0%</option></select></td><td class="num" data-detail-amount>0円</td><td><button class="remove-detail" type="button" aria-label="明細を削除">削除</button></td>`;row.querySelector('[name="detailName"]').addEventListener('input',updateSingleTotals);row.querySelector('[name="detailUnit"]').addEventListener('input',updateSingleTotals);row.querySelector('[name="detailTaxRate"]').addEventListener('input',updateSingleTotals);bindDetailNumber(row.querySelector('[name="detailUnitPrice"]'),updateSingleTotals);bindDetailNumber(row.querySelector('[name="detailQuantity"]'),updateSingleTotals);row.querySelector('.remove-detail').onclick=()=>{if($$('#singleDetailBody tr').length===1)return alert('明細は1行以上必要です。');row.remove();updateSingleTotals();saveSingleDraft();};$('#singleDetailBody').appendChild(row);updateSingleTotals();if(focusName){saveSingleDraft();setTimeout(()=>row.querySelector('[name="detailName"]').focus(),0);}}
