  async function addSingleInvoice(event){event.preventDefault();if(!validateSingleInvoiceForPreview())return;const button=event.submitter||event.currentTarget.querySelector('[type="submit"]'),sendAfterSave=button?.id==='saveAndSendSingleInvoice',originalText=button?.textContent||'';let saved=null;if(button){button.disabled=true;button.textContent=sendAfterSave?'保存して送信受付中…':'保存中…';}showOperationOverlay(sendAfterSave?'保存して送信を受け付けています':'保存中');saveSingleDraft();setSingleSaveStatus('Cloudflare D1へ保存しています。','working');try{const invoice=currentSingleInvoice();if(state.invoices.some(item=>item.invoiceNumber===invoice.invoiceNumber))throw new Error('同じ請求書番号が発行リストにあります。');invoice.paymentStatus='未入金';invoice.createdAt=new Date().toISOString();saved=await saveInvoiceToD1(invoice);state.invoices.push(saved);state.selectedInvoiceNumber=saved.invoiceNumber;renderCreate();renderInvoices();$('#invoiceImportSummary').innerHTML=cards({'作成方法':sendAfterSave?'テスト送信':'個別作成','追加件数':1,'発行リスト':state.invoices.length,'請求金額':C.formatYen(saved.total)});$('#invoiceImportSummary').classList.remove('hidden');activateStep(4);if(sendAfterSave){setSingleSaveStatus('請求書PDFを準備しています。','working');await api('saveInvoiceData',{invoice:saved});await ensurePdfsForSend([saved]);setSingleSaveStatus('メール送信を受け付けています。','working');await api('enqueueSend',{invoiceNumbers:[saved.invoiceNumber],testMode:false,resend:false,newToken:true});markSendQueued([saved]);resetSingleForm();showView('invoices');alert(`${saved.invoiceNumber} ${saved.partnerName}の請求書を保存し、メール送信を受け付けました。バックグラウンドで送信されます。`,'success');setTimeout(()=>refreshAll(false),65000);}else{resetSingleForm();showView('invoices');alert(`${saved.invoiceNumber} ${saved.partnerName}の請求書をD1へ保存しました。`,'success');}}catch(e){const message=saved?`請求書は保存しましたが、送信を受け付けられませんでした：${e.message}`:`請求書は保存されていません。${e.message}`;if(saved){state.selectedInvoiceNumber=saved.invoiceNumber;renderCreate();renderInvoices();resetSingleForm();showView('invoices');}else setSingleSaveStatus(message,'error');alert(message,'error');}finally{hideOperationOverlay();if(button){button.disabled=false;button.textContent=originalText;}}}
  const invoiceSortValue=invoice=>{const date=Date.parse(String(invoice.createdAt||invoice.invoiceDate||'').replace(/\//g,'-'));return Number.isFinite(date)?date:0;};
  const sortedInvoices=()=>state.invoices.slice().sort((a,b)=>invoiceSortValue(b)-invoiceSortValue(a)||String(b.invoiceNumber).localeCompare(String(a.invoiceNumber),'ja'));
  const selectedInvoice=()=>state.invoices.find(invoice=>String(invoice.invoiceNumber)===String(state.selectedInvoiceNumber));
  const paymentClass=status=>status==='入金済'?'paid':status==='未設定'?'unset':'unpaid';
  const inputDate=value=>{const match=String(value||'').match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/);return match?`${match[1]}-${match[2].padStart(2,'0')}-${match[3].padStart(2,'0')}`:'';};
  const invoiceForOutput=invoice=>({...invoice,bank:invoice.bank||state.settings.defaultBank||'',note:invoice.note||state.settings.defaultNote||'個別指導ステップ（運営：株式会社エデュクレスト）'});
  const isDeliveredInvoice=invoice=>C.isSentStatus(invoice.sendStatus)||['URLアクセス済み','DL済'].includes(String(invoice.dlStatus||''));
  const normalizeSearch=value=>String(value??'').normalize('NFKC').toLocaleLowerCase('ja').replace(/[\s　]+/g,'');
  function invoiceSearchText(invoice){return normalizeSearch([invoice.invoiceNumber,invoice.customerCode,invoice.partnerName,invoice.honorific,invoice.subject,invoice.memo,invoice.tags,invoice.note,invoice.email,invoice.cc,invoice.postal,invoice.prefecture,invoice.address1,invoice.address2,invoice.paymentStatus,invoice.sendStatus,invoice.invoiceDate,invoice.dueDate,invoice.createdAt,invoice.updatedAt,...(invoice.details||[]).flatMap(detail=>[detail.name,detail.itemCode,detail.unit,detail.unitPrice,detail.quantity,detail.amount,detail.taxRate])].join(' '));}
  function filteredInvoices(){const {dateField,from,to,query}=state.invoiceFilters,needle=normalizeSearch(query);return sortedInvoices().filter(invoice=>{const date=inputDate(invoice[dateField]);if((from||to)&&!date)return false;if(from&&date<from)return false;if(to&&date>to)return false;return !needle||invoiceSearchText(invoice).includes(needle);});}
  async function saveImportedInvoicesToList(){const buttons=$$('[data-save-imported-invoices]'),items=[...state.createSelected].sort((a,b)=>a-b).map(index=>state.importInvoices[index]).filter(Boolean);if(!items.length)return alert('保存する請求書を選択してください。','error');if(!staffSessionToken()){const message='請求書を保存するにはスタッフログインが必要です。右上の「スタッフログイン」からログイン後、請求書システムへ戻ってCSVをもう一度選択してください。';$('#invoiceImportSummary').innerHTML=cards({'保存状況':'スタッフログインが必要','未保存':`${items.length}件`});$('#invoiceImportSummary').classList.remove('hidden');buttons.forEach(button=>button.textContent='スタッフログインして保存');alert(message,'error');const login=$('#staffLoginLink');login?.scrollIntoView({behavior:'smooth',block:'center'});login?.focus();return;}buttons.forEach(button=>{button.disabled=true;button.textContent='保存しています…';});showOperationOverlay(`0／${items.length}件を保存しています…`);let next=0,savedCount=0;const saved=new Array(items.length),createdAt=new Date().toISOString();try{const worker=async()=>{while(true){const index=next++;if(index>=items.length)return;const invoice={...items[index],paymentStatus:items[index].paymentStatus||'未入金',createdAt};delete invoice.originalInvoiceNumber;saved[index]=await saveInvoiceToD1(invoice);savedCount+=1;$('#operationOverlayText').textContent=`${savedCount}／${items.length}件を保存しています…`;}};await Promise.all(Array.from({length:Math.min(5,items.length)},worker));buttons.forEach(button=>button.textContent='保存しました');state.importInvoices=[];state.createSelected.clear();renderCreate();await refreshAll(false);state.selectedInvoiceNumber=saved[0]?.invoiceNumber||'';activateStep(5);showView('invoices');alert(`${saved.length}件の請求書を新規作成しました。`,'success');}catch(e){const savedNumbers=new Set(saved.filter(Boolean).map(invoice=>String(invoice.invoiceNumber)));state.importInvoices=state.importInvoices.filter(invoice=>!savedNumbers.has(String(invoice.invoiceNumber)));state.createSelected=new Set(state.importInvoices.map((_,index)=>index));await refreshAll(false);renderCreate();$('#invoiceImportSummary').innerHTML=cards({'保存済み':`${savedCount}件`,'未保存':`${state.importInvoices.length}件`,'エラー':e.message});$('#invoiceImportSummary').classList.remove('hidden');alert(`${savedCount}件を作成した後、処理を中断しました：${e.message}`,'error');}finally{hideOperationOverlay();updateCreateSelectionUi();}}
  function updateInvoiceSelectionUi(visible=filteredInvoices().slice(0,state.invoiceVisibleLimit)){const valid=new Set(state.invoices.map((_,i)=>i));for(const index of [...state.selected])if(!valid.has(index))state.selected.delete(index);const summary=$('#invoiceBulkSummary');if(summary)summary.textContent=`選択した${state.selected.size}件を一括操作する`;const menu=$('#invoiceBulkMenu');if(menu)menu.classList.toggle('disabled',state.selected.size===0);const master=$('#invoiceSelectAllVisible'),visibleIndices=visible.map(inv=>state.invoices.indexOf(inv)).filter(i=>i>=0),selectedVisible=visibleIndices.filter(i=>state.selected.has(i)).length;if(master){master.checked=visibleIndices.length>0&&selectedVisible===visibleIndices.length;master.indeterminate=selectedVisible>0&&selectedVisible<visibleIndices.length;master.disabled=visibleIndices.length===0;}}
  function updateInvoiceFilters(){state.invoiceFilters={dateField:$('#invoiceDateField').value,from:$('#invoiceDateFrom').value,to:$('#invoiceDateTo').value,query:$('#invoiceFreeSearch').value};state.invoiceVisibleLimit=100;renderInvoices();}
