  async function updatePaymentStatus(invoice,value,paymentDate='',paymentAmount='',paymentMemo=''){const before=invoice.paymentStatus||'未入金',beforeDate=invoice.paymentDate||'',beforeAmount=invoice.paymentAmount,beforeMemo=invoice.paymentMemo||'';invoice.paymentStatus=value;invoice.paymentDate=value==='入金済'?paymentDate:'';invoice.paymentAmount=value==='入金済'?Number(paymentAmount):'';invoice.paymentMemo=value==='入金済'?String(paymentMemo||''):'';renderInvoices();try{const data=await cloudApi(`/api/app/invoices/${encodeURIComponent(invoice.invoiceNumber)}/payment`,{method:'POST',body:{paymentStatus:value,paymentDate:invoice.paymentDate,paymentAmount:invoice.paymentAmount,paymentMemo:invoice.paymentMemo}});Object.assign(invoice,data.invoice);renderInvoices();alert(value==='入金済'?`入金日 ${invoice.paymentDate}、入金金額 ${C.formatYen(invoice.paymentAmount)} で「入金済」に変更しました。`:`入金状態を「${value}」に変更しました。`,'success');}catch(e){invoice.paymentStatus=before;invoice.paymentDate=beforeDate;invoice.paymentAmount=beforeAmount;invoice.paymentMemo=beforeMemo;renderInvoices();alert(e.message,'error');}}
  async function savePaymentDate(event){event.preventDefault();const invoice=state.pendingPaymentInvoice,date=$('#paymentDateInput').value,amountInput=$('#paymentAmountInput'),memo=$('#paymentMemoInput').value.trim();normalizeDetailNumber(amountInput);const amount=Number(amountInput.value);if(!invoice||!date)return;if(!Number.isFinite(amount)||amount<0){amountInput.focus();return alert('入金金額を0以上の数字で入力してください。','error');}$('#paymentDateDialog').close();state.pendingPaymentInvoice=null;await updatePaymentStatus(invoice,'入金済',date,amount,memo);}
  function invoiceAction(action,invoice){if(action==='edit'){if(isDeliveredInvoice(invoice)&&!window.confirm('この請求書はすでに送信またはダウンロードされています。\n\n編集内容を保存しただけでは、相手へ送信済みのURLにあるPDFは変わりません。再送すると新しいPDFとURLが発行され、相手は新しい内容を確認できます。\n\n内容を十分確認して編集しますか？'))return;return openInvoiceEdit(invoice);}if(action==='duplicate_invoice')return window.StepReceipts?.openInvoiceDuplicate(invoice);if(action==='convert_receipt')return window.StepReceipts?.openReceiptFromInvoice(invoice);if(action==='duplicate')return window.StepReceipts?.openInvoiceDuplicate(invoice);if(action==='delete')return openInvoiceDelete(invoice);if(action==='mail')return openInvoiceMail(invoice);if(action==='pdf')return openInvoicePdf(invoice);}
  function openInvoiceMail(invoice){state.preview=invoice;const form=$('#mailForm'),settings={senderName:form.elements.senderName.value||'個別指導ステップ【請求書】',replyTo:form.elements.replyTo.value||'',subject:form.elements.subject.value||'【請求書】送付のご案内（個別指導ステップから）',body:form.elements.body.value||'',testRecipient:form.elements.testRecipient.value||''};$('#mailInvoiceNumber').textContent=invoice.invoiceNumber;$('#mailTo').textContent=invoice.email;$('#mailCc').textContent=invoice.cc||'なし';$('#mailSender').textContent=settings.senderName;$('#mailReplyTo').textContent=settings.replyTo||'なし';$('#mailSubject').value=settings.subject;$('#mailBody').value=C.renderTemplate(settings.body,{'取引先名':invoice.partnerName,'敬称':invoice.honorific||'様','有効日数':form.elements.validDays.value||45,'ダウンロードURL':'（送信時にCloudflareのURLを発行します）'});const pending=['送信待ち','送信中'].includes(String(invoice.sendStatus||'')),resend=C.isSentStatus(invoice.sendStatus);const button=$('#confirmInvoiceMail');button.textContent=pending?'送信受付済み':resend?'この内容で再送':'この内容で送信';button.disabled=pending;const status=$('#invoiceMailStatus');status.textContent=pending?'この請求書は送信受付済みです。バックグラウンドで処理されます。':'';status.className=pending?'mail-submit-status working':'mail-submit-status hidden';$('#invoiceMailDialog').showModal();}
  async function confirmInvoiceMail(){const invoice=state.preview;if(!invoice)return;const pending=['送信待ち','送信中'].includes(String(invoice.sendStatus||'')),button=$('#confirmInvoiceMail'),resend=C.isSentStatus(invoice.sendStatus),idleText=pending?'送信受付済み':resend?'この内容で再送':'この内容で送信',status=$('#invoiceMailStatus');if(pending){$('#invoiceMailDialog').close();return alert('この請求書は既に送信受付済みです。バックグラウンドで処理されます。','success');}button.disabled=true;button.textContent='保存を確認しています…';status.textContent='請求書の台帳保存を確認しています。';status.className='mail-submit-status working';try{await api('saveInvoiceData',{invoice});button.textContent='PDFを準備しています…';status.textContent='請求書PDFを準備しています。';await ensurePdfsForSend([invoice]);button.textContent='送信を受け付けています…';status.textContent='メール送信を受け付けています。';await api('enqueueSend',{invoiceNumbers:[invoice.invoiceNumber],testMode:false,resend,newToken:true});markSendQueued([invoice]);$('#invoiceMailDialog').close();alert(resend?'再送を受け付けました。バックグラウンドで送信されます。':'メール送信を受け付けました。バックグラウンドで送信されます。','success');setTimeout(()=>refreshAll(false),65000);}catch(e){status.textContent=`送信を受け付けられませんでした：${e.message}`;status.className='mail-submit-status error';alert(`送信を受け付けられませんでした：${e.message}`,'error');}finally{button.disabled=false;button.textContent=idleText;}}
  function openInvoicePdf(invoice){state.preview=invoice;$('#pdfInvoiceTarget').textContent=`${invoice.partnerName} 様　請求書 No. ${invoice.invoiceNumber}`;$('#invoicePdfDialog').showModal();}
  function editDetailRows(){return $$('#editInvoiceDetailBody tr').map(row=>({name:row.querySelector('[name="editDetailName"]').value,unitPrice:Number(row.querySelector('[name="editDetailUnitPrice"]').value||0),quantity:Number(row.querySelector('[name="editDetailQuantity"]').value||0),unit:row.querySelector('[name="editDetailUnit"]').value,taxRate:Number(row.querySelector('[name="editDetailTaxRate"]').value||0)}));}
