  function addEditDetail(data={},focusName=false){const row=document.createElement('tr'),tax=Number(String(data.taxRate??10).replace('%',''));row.innerHTML=`<td><input name="editDetailName" type="text" inputmode="text" lang="ja" autocomplete="off" value="${esc(data.name||'')}" required></td><td><input name="editDetailUnitPrice" type="text" inputmode="decimal" value="${esc(data.unitPrice??'')}" required></td><td><input name="editDetailQuantity" type="text" inputmode="decimal" value="${esc(data.quantity??1)}" required></td><td><input name="editDetailUnit" type="text" inputmode="text" lang="ja" value="${esc(data.unit||'')}"></td><td><select name="editDetailTaxRate"><option value="10" ${tax===10?'selected':''}>10%</option><option value="8" ${tax===8?'selected':''}>8%</option><option value="0" ${tax===0?'selected':''}>0%</option></select></td><td data-edit-detail-amount>0円</td><td><button class="remove-detail" type="button">削除</button></td>`;row.querySelector('[name="editDetailName"]').addEventListener('input',updateEditTotals);row.querySelector('[name="editDetailUnit"]').addEventListener('input',updateEditTotals);row.querySelector('[name="editDetailTaxRate"]').addEventListener('input',updateEditTotals);bindDetailNumber(row.querySelector('[name="editDetailUnitPrice"]'),updateEditTotals);bindDetailNumber(row.querySelector('[name="editDetailQuantity"]'),updateEditTotals);row.querySelector('.remove-detail').onclick=()=>{if($$('#editInvoiceDetailBody tr').length<2)return alert('明細は1行以上必要です。');row.remove();updateEditTotals();};$('#editInvoiceDetailBody').appendChild(row);updateEditTotals();if(focusName)setTimeout(()=>row.querySelector('[name="editDetailName"]').focus(),0);}
  function openInvoiceEdit(invoice){state.preview=invoice;const form=$('#editInvoiceForm');form.reset();form.elements.partnerName.value=invoice.partnerName||'';form.elements.invoiceNumber.value=invoice.invoiceNumber;form.elements.subject.value=invoice.subject||'';form.elements.invoiceDate.value=inputDate(invoice.invoiceDate);form.elements.dueDate.value=inputDate(invoice.dueDate);form.elements.memo.value=invoice.memo||'';form.elements.tags.value=invoice.tags||'';form.elements.paymentStatus.value=invoice.paymentStatus||'未入金';form.elements.paymentDate.value=inputDate(invoice.paymentDate);form.elements.paymentAmount.value=String(invoice.paymentAmount??invoice.total??0);form.elements.bank.value=invoice.bank||'';form.elements.note.value=invoice.note||'';$('#editInvoiceDetailBody').innerHTML='';(invoice.details?.length?invoice.details:[{name:'請求内容',unitPrice:invoice.subtotal||0,quantity:1,unit:'',taxRate:10}]).forEach(addEditDetail);$('#editInvoiceDialog').showModal();}
  async function saveInvoiceEdit(event){event.preventDefault();const original=state.preview;if(!original)return;showOperationOverlay('保存中');try{normalizeDetailNumber(event.currentTarget.elements.paymentAmount);const values=Object.fromEntries(new FormData(event.currentTarget).entries()),rows=editDetailRows();if(!rows.length||rows.some(row=>!row.name||!Number.isFinite(row.unitPrice)||row.quantity<=0))throw new Error('請求明細を正しく入力してください。');if(values.paymentStatus==='入金済'&&!values.paymentDate)throw new Error('入金済にする場合は入金日を入力してください。');if(values.paymentStatus==='入金済'&&(!Number.isFinite(Number(values.paymentAmount))||Number(values.paymentAmount)<0))throw new Error('入金済にする場合は入金金額を0以上の数字で入力してください。');if(values.paymentStatus==='入金済')values.paymentAmount=Number(values.paymentAmount);else{values.paymentDate='';values.paymentAmount='';}const details=rows.map(row=>{const amount=Math.round(row.unitPrice*row.quantity);return {deliveryDate:'',name:row.name,itemCode:'',unitPrice:row.unitPrice,quantity:row.quantity,unit:row.unit,deliveryNumber:'',detail:'',amount,withholding:'含まない',taxRate:`${row.taxRate}%`};}),subtotal=details.reduce((sum,row)=>sum+row.amount,0),sourceTax=rows.reduce((sum,row)=>sum+Math.round(row.unitPrice*row.quantity*row.taxRate/100),0),total=C.roundToNearest10(subtotal+sourceTax),updated={...original,...values,details,subtotal,sourceTax,sourceTotal:subtotal+sourceTax,tax:total-subtotal,total,pdfStatus:'未作成',pdfFileId:'',pdfFileName:'',updatedAt:new Date().toISOString()};const saved=await saveInvoiceToD1(updated);const index=state.invoices.findIndex(item=>String(item.invoiceNumber)===String(saved.invoiceNumber));state.invoices[index]=saved;state.preview=saved;$('#editInvoiceDialog').close();renderCreate();renderInvoices();alert('請求書の変更をD1へ保存しました。送信済みPDFを更新する場合は再送してください。','success');}catch(e){alert(e.message,'error');}finally{hideOperationOverlay();}}
  async function duplicateInvoice(invoice){showOperationOverlay('保存中');try{const today=localIso(new Date()),copy=JSON.parse(JSON.stringify(invoice));copy.invoiceNumber=C.nextInvoiceNumber(today,state.invoices);copy.invoiceDate=today;copy.dueDate=plusDays(today,21);copy.createdAt=new Date().toISOString();copy.updatedAt=new Date().toISOString();copy.paymentStatus='未入金';copy.paymentDate='';copy.paymentAmount='';copy.paymentMemo='';copy.pdfStatus='未作成';copy.pdfFileId='';copy.pdfFileName='';copy.sendStatus='未送信';copy.sentAt='';copy.dlStatus='未取得';copy.downloadedAt='';copy.expiresAt='';const saved=await saveInvoiceToD1(copy);state.invoices.push(saved);state.selectedInvoiceNumber=saved.invoiceNumber;renderCreate();renderInvoices();alert(`請求書を複製しました。新しい請求書番号は ${saved.invoiceNumber} です。`,'success');openInvoiceEdit(saved);}catch(e){alert(`複製できませんでした：${e.message}`,'error');}finally{hideOperationOverlay();}}
