  async function confirmSend(){
    let groups=classifyQueueSelection(selectedItems());
    if(groups.resend.length){$('#sendDialog').close();return openResendDialog(groups);}
    if(!groups.unsent.length)return;
    const button=$('#confirmSend');button.disabled=true;button.textContent='PDFを準備しています…';
    try{await ensurePdfsForSend(groups.unsent);groups=classifyQueueSelection(selectedItems());button.textContent='送信を受け付けています…';const result=await api('enqueueSend',{invoiceNumbers:groups.unsent.map(x=>x.invoiceNumber),testMode:false,resend:false,newToken:true});markSendQueued(groups.unsent);$('#sendDialog').close();alert(`${result?.queued||groups.unsent.length}件の送信を受け付けました。画面を閉じてもバックグラウンドで送信されます。`,'success');setTimeout(()=>refreshAll(false),65000);}catch(e){alert(`送信を受け付けられませんでした：${e.message}`,'error');}finally{button.disabled=false;button.textContent=`選択した${groups.unsent.length}件を送信`;}
  }
  async function confirmResend(){
    if(state.resendSubmitting||!state.pendingResend)return;
    state.resendSubmitting=true;
    let groups=state.pendingResend;const button=$('#confirmResend');button.disabled=true;button.textContent='PDFを準備しています…';
    try{
      await ensurePdfsForSend([...groups.unsent,...groups.resend]);groups=classifyQueueSelection(groups.selected);button.textContent='再送を受け付けています…';
      if(groups.unsent.length)await api('enqueueSend',{invoiceNumbers:groups.unsent.map(x=>x.invoiceNumber),testMode:false,resend:false,newToken:true});
      if(groups.resend.length)await api('enqueueSend',{invoiceNumbers:groups.resend.map(x=>x.invoiceNumber),testMode:false,resend:true,newToken:true});
      markSendQueued([...groups.unsent,...groups.resend]);$('#resendDialog').close();alert(`${groups.unsent.length+groups.resend.length}件の送信を受け付けました。バックグラウンドで順次送信されます。`,'success');state.pendingResend=null;setTimeout(()=>refreshAll(false),65000);
    }catch(e){alert(e.message,'error');button.disabled=false;button.textContent='再送する';}finally{state.resendSubmitting=false;}
  }
